'use strict';
const process = require('process');

function clock() {
  let ms;
  if (typeof process.hrtime === 'function') {
    const t = process.hrtime();
    ms = t[0] * 1e3 + t[1] * 1e-6;
  } else {
    ms = process.uptime() * 1000;
  }
  return ms >= 0;
}

function probe() {
  return ['getBuiltinModule' in process, 'noSuchMember' in process, typeof process.uptime].join(',');
}

module.exports = { clock, probe };
